+            payloads.sort_by_key(|payload| payload.target);
+            let verification_policy = payloads
+                .first()
+                .expect("closed product roster contains product payloads")
+                .provenance_policy
+                .clone();
+            let metadata = Self {
+                schema_version: Self::SCHEMA_VERSION,
+                product_release: intent.product_release.clone(),
+                intent_digest: intent.digest.clone(),
