+        #[test]
+        fn manifest_metadata_and_checksum_are_bound_without_circularity() {
+            let intent = intent();
+            let entries = intent
+                .slots
+                .iter()
+                .filter(|slot| {
+                    matches!(
+                        slot,
+                        ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
+                    )
+                })
+                .cloned()
+                .map(|slot| ReleaseArtifactEntry {
+                    digest: ArtifactDigest::from_bytes(slot.file_name().as_bytes()),
+                    byte_length: slot.file_name().len() as u64,
+                    source_commit: commit(),
+                    provenance: slot.policy().clone(),
+                    slot,
+                })
+                .collect::<Vec<_>>();
+            let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
+            let other_intent = ReleaseIntent::new(
+                intent.product_release.clone(),
+                CommitSha::parse(&"b".repeat(40)).unwrap(),
+                intent.registry_packages.clone(),
+                intent.operations.clone(),
+                intent.slots.clone(),
+            )
+            .unwrap();
+            assert!(ReleaseDistributionMetadataV1::from_payloads(&other_intent, &payloads).is_err());
+            let metadata = ReleaseDistributionMetadataV1::from_payloads(&intent, &payloads).unwrap();
+            let manifest = ReleaseArtifactManifest::complete(&intent, &payloads).unwrap();
+            assert_eq!(manifest.entries.len(), 6);
+            assert!(manifest.validate_for_intent(&intent).is_ok());
+            assert_eq!(
+                serde_json::from_value::<ReleaseArtifactManifest>(serde_json::to_value(&manifest).unwrap()).unwrap(),
+                manifest
+            );
+            assert_eq!(
+                serde_json::from_value::<ReleaseDistributionMetadataV1>(serde_json::to_value(&metadata).unwrap())
+                    .unwrap(),
+                metadata
+            );
+            let mut forged = manifest.clone();
+            forged.entries[0].source_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
+            assert!(forged.validate_for_intent(&intent).is_err());
+            let mut forged_metadata = manifest.clone();
+            forged_metadata
+                .entries
+                .iter_mut()
+                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
+                .unwrap()
+                .byte_length += 1;
+            assert!(forged_metadata.validate_for_intent(&intent).is_err());
+            let mut forged_checksum = manifest.clone();
+            forged_checksum
+                .entries
+                .iter_mut()
+                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
+                .unwrap()
+                .digest = ArtifactDigest::from_bytes("forged");
+            assert!(forged_checksum.validate_for_intent(&intent).is_err());
+            let mut metadata_wire = serde_json::to_value(metadata).unwrap();
+            metadata_wire["unknown"] = serde_json::Value::Bool(true);
+            assert!(serde_json::from_value::<ReleaseDistributionMetadataV1>(metadata_wire).is_err());
+        }
