            assert!(!is_release_unit(&ws.config, &fixture.id).unwrap());
            let plan = plan_version(&ws, &NoInference, &VersionOptions::default()).unwrap();
            assert!(
                !plan
                    .diagnostics
                    .iter()
                    .any(|diagnostic| diagnostic.severity == callisto_model::DiagnosticSeverity::Error),
                "{:?}",
                plan.diagnostics
            );
            let source_bump = plan.bumps.iter().find(|bump| bump.package == fixture.id).unwrap();
            let fixture_target = source_bump.to.clone();
            assert!(source_bump.writes.iter().any(|write| matches!(write, callisto_graph::plan::VersionWriteTarget::Manifest(path) if path == Path::new("crates/callisto-fixtures/Cargo.toml"))));
            assert!(!plan
                .changelog_writes
                .iter()
                .any(|write| write.changelog_path.starts_with("crates/callisto-fixtures")));
            let mut decision = derive_release_decision(&ws, &plan).unwrap();
            assert_eq!(decision.entries.len(), ws.graph.packages().count() - 1);
            assert!(decision
                .entries
                .iter()
                .all(|entry| entry.package.name() != "callisto-fixtures" && entry.target_version == fixture_target));
            let fixture_id = ReleasePackageId::new(Ecosystem::Cargo, "callisto-fixtures").unwrap();
            assert!(derive_selected_release_decision(&ws, &plan, std::slice::from_ref(&fixture_id)).is_err());
            if tamper == "fixture-entry" {
                let mut entries = decision.entries;
                entries.push(ReleaseDecisionEntry {
                    package: fixture_id,
                    target_version: fixture_target.clone(),
                    reasons: vec![ReleaseInclusionReason::ExplicitSelection],
                });
                decision = ReleaseDecisionV1::new(entries).unwrap();
            } else if tamper == "fixture-reason" {
                let mut entries = decision.entries;
                entries[0].reasons = vec![ReleaseInclusionReason::Cascade {
                    from: fixture_id,
                    edge_kind: "dev".to_string(),
                }];
                decision = ReleaseDecisionV1::new(entries).unwrap();
            } else if tamper == "unclaimed-package" {
                decision = ReleaseDecisionV1::new(
                    decision
                        .entries
                        .into_iter()
                        .filter(|entry| entry.package.name() != "callisto-format")
                        .collect(),
                )
                .unwrap();
            }
            apply_version_plan(
                root,
                &plan,
                &GitRunner,
                &ApplyOptions::default(),
                &ApplyPermit::force_for_tests(),
            )
            .unwrap();
            drop(ws);
            if tamper == "fixture-target" {
                let path = root.join("crates/callisto-fixtures/Cargo.toml");
                let mut manifest: toml_edit::DocumentMut = fs::read_to_string(&path).unwrap().parse().unwrap();
                manifest["package"]["version"] = toml_edit::value("99.0.0");
                callisto_model::atomic::atomic_write(&path, &manifest.to_string(), &ApplyPermit::force_for_tests())
                    .unwrap();
            }
            fs::create_dir_all(root.join(".callisto")).unwrap();
            let decision_path = Path::new(".callisto/release-decision.json");
            fs::write(root.join(decision_path), serde_json::to_vec(&decision).unwrap()).unwrap();
            git(root, &["add", "."]);
            git(root, &["commit", "-qm", "version train"]);
            let commit = CommitSha::parse(&git(root, &["rev-parse", "HEAD"])).unwrap();
            let ws = Workspace::load(root.to_path_buf(), &locator, &GitRunner).unwrap();
            let verified = derive_release_commit_decision(&ws, &commit, decision_path);
            if tamper == "none" {
                assert_eq!(verified.unwrap(), decision);
            } else {
                assert!(verified.is_err(), "accepted {tamper}");
            }
        }
    }

    #[test]
    fn dev_only_changeset_cannot_seed_train_or_pass_validation() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        copy_repository_manifests(root);
        fs::write(
            root.join(".changeset/train.md"),
            "---\n\"callisto-fixtures\": major\n---\n\nOnly development fixtures changed.\n",
        )
        .unwrap();
        let ws = Workspace::load(root.to_path_buf(), &IgnoreWalkLocator::new(root), &GitRunner).unwrap();
        let plan = plan_version(&ws, &NoInference, &VersionOptions::default()).unwrap();
        assert!(plan.bumps.is_empty());
        assert!(plan.consumed_changesets.is_empty());
        let report =
            callisto_graph::commands::validate(&ws, &callisto_graph::commands::ValidateOptions::default()).unwrap();
        assert!(!report.ok);
        assert!(report
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.message.contains("dev-only package")));
    }
}

