use callisto_model::{CommandRunner, ValidateReport, SCHEMA_VERSION};

use crate::aggregate::LoadedChangeset;
use crate::commands::escalate;
use crate::error::GraphError;
use crate::resolver::DependencyResolver;
use crate::Workspace;

/// Runs a `git diff --name-only`-shaped command and filters `loaded` down to
/// changesets whose path matches one of the changed files. Shared by the
/// `--staged` and `--since` branches of [`validate`], which differ only in
/// the git args they pass.
fn changesets_touched_by<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    args: &[&str],
    loaded: Vec<LoadedChangeset>,
) -> Result<Vec<LoadedChangeset>, GraphError> {
    let out = ws.runner.run("git", args, &ws.root)?;
    if !out.success() {
        return Err(GraphError::Command(callisto_model::CommandError::Io {
            program: "git".to_string(),
            message: out.redacted_stderr(),
        }));
    }
    let files: Vec<String> = out
        .stdout_trimmed()
        .lines()
        .map(|l| l.trim_matches('"').to_string())
        .collect();
    Ok(loaded
        .into_iter()
        .filter(|cs| files.iter().any(|f| cs.path.ends_with(f)))
        .collect())
}

#[derive(Clone, Debug, Default)]
pub struct ValidateOptions {
    pub staged: bool,
    pub since: Option<String>,
    pub strict: bool,
    pub strict_graph: bool,
}

pub fn validate<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    opts: &ValidateOptions,
) -> Result<ValidateReport, GraphError> {
    let mut diagnostics = Vec::new();
    let loaded = crate::load_changesets(&ws.root, &ws.config)?;

    let target_changesets: Vec<_> = if opts.staged {
        changesets_touched_by(ws, &["diff", "--cached", "--name-only"], loaded)?
    } else if let Some(ref since) = opts.since {
        if since.starts_with('-') {
            return Err(GraphError::Command(callisto_model::CommandError::Io {
                program: "git".to_string(),
                message: "invalid since ref".to_string(),
            }));
        }
        let range = format!("{since}..HEAD");
        changesets_touched_by(ws, &["diff", "--name-only", &range, "--"], loaded)?
    } else {
        loaded
    };

    for cs in &target_changesets {
        if cs.changeset.entries.is_empty() {
            diagnostics.push(callisto_model::Diagnostic {
                code: callisto_model::DiagnosticCode::EmptyChangeset,
                severity: callisto_model::DiagnosticSeverity::Error,
                message: format!("Changeset `{}` is empty", cs.path.display()),
                package: None,
                path: Some(cs.path.clone()),
                governed_by: None,
                escalated_by: None,
            });
        }

        if !cs.changeset.entries.is_empty() && cs.changeset.summary.trim().is_empty() {
            diagnostics.push(callisto_model::Diagnostic {
                code: callisto_model::DiagnosticCode::EmptySummary,
                severity: callisto_model::DiagnosticSeverity::Error,
                message: format!("Changeset `{}` has entries but an empty summary", cs.path.display()),
                package: None,
                path: Some(cs.path.clone()),
                governed_by: None,
                escalated_by: None,
            });
        }

        for entry in &cs.changeset.entries {
            match callisto_model::PackageId::parse(&entry.name) {
                Ok(id) => match id.resolve_unique(ws.graph.packages(), |p| &p.id) {
                    Ok(None) => {
                        diagnostics.push(callisto_model::Diagnostic {
                            code: callisto_model::DiagnosticCode::UnknownPackage,
                            severity: callisto_model::DiagnosticSeverity::Error,
                            message: format!(
                                "Changeset `{}` references unknown package `{}`",
                                cs.path.display(),
                                entry.name
                            ),
                            package: Some(id),
                            path: Some(cs.path.clone()),
                            governed_by: None,
                            escalated_by: None,
                        });
                    }
                    Ok(Some(package)) => {
                        if !crate::config::is_release_unit(&ws.config, &package.id)? {
                            diagnostics.push(callisto_model::Diagnostic {
                                code: callisto_model::DiagnosticCode::UnknownPackage,
                                severity: callisto_model::DiagnosticSeverity::Error,
                                message: format!("Changeset `{}` references dev-only package `{}`; remove this entry because it is not a release unit", cs.path.display(), entry.name),
                                package: Some(package.id.clone()),
                                path: Some(cs.path.clone()),
                                governed_by: None,
                                escalated_by: None,
                            });
                        }
                    }
                    Err(candidates) => {
                        let names: Vec<String> = candidates.iter().map(|p| p.id.display_name().to_string()).collect();
                        diagnostics.push(callisto_model::Diagnostic {
                            code: callisto_model::DiagnosticCode::AmbiguousPackageName,
                            severity: callisto_model::DiagnosticSeverity::Error,
                            message: format!(
                                "Changeset `{}` references ambiguous package `{}` (matches: {})",
                                cs.path.display(),
                                entry.name,
                                names.join(", ")
                            ),
                            package: Some(id),
                            path: Some(cs.path.clone()),
                            governed_by: None,
                            escalated_by: None,
                        });
                    }
                },
                Err(_) => {
                    diagnostics.push(callisto_model::Diagnostic {
                        code: callisto_model::DiagnosticCode::InvalidPackageName,
                        severity: callisto_model::DiagnosticSeverity::Error,
                        message: format!(
                            "Changeset `{}` contains invalid package name `{}`",
                            cs.path.display(),
                            entry.name
                        ),
                        package: None,
                        path: Some(cs.path.clone()),
                        governed_by: None,
                        escalated_by: None,
                    });
                }
            }
        }
    }

    escalate(&mut diagnostics, opts.strict, opts.strict_graph);

    let is_valid = diagnostics
        .iter()
        .all(|d| d.severity != callisto_model::DiagnosticSeverity::Error);
    Ok(ValidateReport {
        schema_version: SCHEMA_VERSION,
        ok: is_valid,
        diagnostics,
    })
}

