 182	/// Verifies the release roster a merged release commit claims, against a
 183	/// release-decision file committed alongside it at `decision_path`.
 184	///
 185	/// This is intentionally *not* a second computation of changeset, fixed-group,
 186	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
 187	/// (via [`derive_release_decision`]) already computed that once, correctly,
 188	/// when the release PR was generated -- and `callisto version --emit-decision`
 189	/// commits its exact output alongside the manifest and changelog edits.
 190	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
 191	/// the kind of duplicated logic that drifts: an earlier version of this
 192	/// function did just that, understood only a direct changeset match, and
 193	/// rejected every real release in this repository once a fixed-group cascade
 194	/// (a case its reimplementation never learned) touched an unnamed sibling.
 195	///
 196	/// Instead, this function reads the committed decision back and confirms the
 197	/// commit's actual diff matches it exactly -- no more, no less.
 198	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
 199	/// entries don't match its content digest, so a hand-edited or corrupted
 200	/// decision file fails before this function's own diff cross-check runs.
 201	///
 202	/// The caller must check out the exact merge commit in detached HEAD state
 203	/// before creating an intent. GitHub-specific PR/approval provenance belongs
 204	/// in the workflow boundary; this graph function verifies the local,
 205	/// provider-neutral commit delta only.
 206	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
 207	    workspace: &Workspace<'_, R, D>,
 208	    release_commit: &CommitSha,
 209	    decision_path: &std::path::Path,
 210	) -> Result<ReleaseDecisionV1, GraphError> {
 211	    let head_args = ["rev-parse", "HEAD"];
 212	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
 213	    let head =
 214	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
 215	    if &head != release_commit {
 216	        return Err(GraphError::ReleaseCommitVerificationFailed {
 217	            commit: release_commit.clone(),
 218	            reason: CommitVerificationFailure::HeadMismatch,
 219	        });
 220	    }
 221	
 222	    let parent_ref = format!("{}^", release_commit.as_str());
 223	    let parent_args = ["rev-parse", parent_ref.as_str()];
 224	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
 225	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
 226	
 227	    let diff_tree_args = [
 228	        "diff-tree",
 229	        "--no-commit-id",
 230	        "--name-status",
 231	        "-r",
 232	        "--no-renames",
 233	        parent.as_str(),
 234	        release_commit.as_str(),
 235	    ];
 236	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
 237	    let changed = parse_name_status(&changed, &diff_tree_args)?;
 238	
 239	    // The decision must be freshly authored as part of *this* commit, not a
 240	    // stale leftover an earlier release already committed and this one never
 241	    // touched -- otherwise a commit that changes nothing real could still
 242	    // carry forward a prior, unrelated decision's authority.
 243	    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
 244	    let decision_freshly_written = changed
 245	        .iter()
 246	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
 247	    if !decision_freshly_written {
 248	        return Err(GraphError::ReleaseCommitVerificationFailed {
 249	            commit: release_commit.clone(),
 250	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
 251	        });
 252	    }
 253	
 254	    // A cheap, independent sanity check that this commit is a real version
 255	    // application and not just a hand-crafted decision file: some real
 256	    // changeset was actually consumed. The decision's own entries, not this
 257	    // changeset's content, remain the sole authority verified below.
 258	    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
 259	    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
 260	    let consumed_a_changeset = changed
 261	        .iter()
 262	        .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
 263	    if !consumed_a_changeset {
 264	        return Err(GraphError::ReleaseCommitVerificationFailed {
 265	            commit: release_commit.clone(),
 266	            reason: CommitVerificationFailure::NoChangesetConsumed,
 267	        });
 268	    }
 269	
 270	    let decision_source = git_file(
 271	        workspace.runner,
 272	        &workspace.root,
 273	        release_commit.as_str(),
 274	        &decision_path_str,
 275	    )?;
 276	    let decision: ReleaseDecisionV1 =
 277	        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
 278	            path: decision_path.to_path_buf(),
 279	            message: error.to_string(),
 280	        })?;
 281	    validate_release_units(workspace, &decision)?;
 282	    let claimed = decision
 283	        .entries
 284	        .iter()
 285	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
 286	        .collect::<std::collections::BTreeMap<_, _>>();
 287	
 288	    let changed_paths = changed
 289	        .iter()
 290	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
 291	        .collect::<std::collections::BTreeSet<_>>();
 292	
 293	    // Every canonical manifest path this workspace currently declares, in
 294	    // the exact order `workspace.graph.packages()` and
 295	    // `Package::canonical_manifests()` yield -- both are backed by ordered
 296	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
 297	    // the second traversal below visits the same (package, manifest) pairs
 298	    // in the same order. That lets it zip the batched `before`/`after`
 299	    // results back on by position instead of re-keying by path, which would
 300	    // misbehave if two packages ever declared an identical manifest path.
 301	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
 302	        .graph
 303	        .packages()
 304	        .flat_map(Package::canonical_manifests)
 305	        .map(|manifest| (manifest.path.to_string_lossy().into_owned(), manifest.ecosystem()))
 306	        .collect();
 307	    let query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
 308	
 309	    // Exactly two `git cat-file --batch` subprocess invocations total (one
 310	    // per commit), regardless of how many canonical manifests the
 311	    // workspace has -- replaces what was previously 2*N separate `git
 312	    // show` spawns (one `manifest_version_at` call per manifest per
 313	    // commit).
 314	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
 315	    let after_blobs =
 316	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
 317	    let before_versions = resolve_batch_versions(before_blobs, &manifest_queries)?;
 318	    let after_versions = resolve_batch_versions(after_blobs, &manifest_queries)?;
 319	
 320	    let mut observed = std::collections::BTreeSet::new();
 321	    let mut manifest_index = 0usize;
 322	    for package in workspace.graph.packages() {
 323	        let package_ids = release_package_ids(package)?;
 324	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
 325	        let releasable = crate::config::is_release_unit(&workspace.config, &package.id)?;
 326	        if package_is_claimed {
 327	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
 328	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
 329	            })?;
 330	            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
 331	                return Err(GraphError::ReleaseCommitVerificationFailed {
 332	                    commit: release_commit.clone(),
 333	                    reason: CommitVerificationFailure::ChangelogNotTouched,
 334	                });
 335	            }
 336	        }
 337	        for (manifest, id) in package.canonical_manifests().zip(package_ids) {
 338	            let path = manifest.path.to_string_lossy();
 339	            let before = &before_versions[manifest_index];
 340	            let after = &after_versions[manifest_index];
 341	            manifest_index += 1;
 342	            let changed_version = before != after;
 343	            match claimed.get(&id) {
 344	                Some(target_version) => {
 345	                    if !changed_paths.contains(path.as_ref()) {
 346	                        return Err(GraphError::ReleaseCommitVerificationFailed {
 347	                            commit: release_commit.clone(),
 348	                            reason: CommitVerificationFailure::ManifestNotInDiff,
 349	                        });
 350	                    }
 351	                    if !changed_version || after != target_version {
 352	                        return Err(GraphError::ReleaseCommitVerificationFailed {
 353	                            commit: release_commit.clone(),
 354	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
 355	                        });
 356	                    }
 357	                    observed.insert(id);
 358	                }
 359	                None => {
 360	                    if changed_version {
 361	                        // A fixed group coordinates source versions even for
 362	                        // members which never own release operations.
 363	                        if !releasable && changed_paths.contains(path.as_ref()) {
 364	                            if let Some(group) = workspace.config.groups.fixed_group_of(&package.id) {
 365	                                let mut group_targets = Vec::new();
 366	                                for member in workspace
 367	                                    .graph
 368	                                    .packages()
 369	                                    .filter(|member| group.package_members().any(|id| id == &member.id))
 370	                                {
 371	                                    if crate::config::is_release_unit(&workspace.config, &member.id)? {
 372	                                        for id in release_package_ids(member)? {
 373	                                            if let Some(target) = claimed.get(&id) {
 374	                                                group_targets.push(target);
 375	                                            }
 376	                                        }
 377	                                    }
 378	                                }
 379	                                if !group_targets.is_empty()
 380	                                    && group_targets.iter().all(|target| *target == after)
 381	                                    && after.partial_compare(before) == Some(std::cmp::Ordering::Greater)
 382	                                {
 383	                                    continue;
 384	                                }
 385	                            }
 386	                        }
 387	                        // A changed version the committed decision never
 388	                        // claimed is not this commit's authority -- fail
 389	                        // closed rather than trust a partial match.
 390	                        return Err(GraphError::ReleaseCommitVerificationFailed {
 391	                            commit: release_commit.clone(),
 392	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
 393	                        });
 394	                    }
 395	                }
 396	            }
 397	        }
 398	    }
 399	    if observed.len() != claimed.len() {
 400	        return Err(GraphError::ReleaseCommitVerificationFailed {
 401	            commit: release_commit.clone(),
 402	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
 403	        });
 404	    }
 405	
 406	    Ok(decision)
 407	}
