 441	fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
 442	    output
 443	        .lines()
 444	        .map(|line| {
 445	            let (status, path) = line.split_once('\t').ok_or_else(|| {
 446	                command_malformed_output(
 447	                    "git",
 448	                    args,
 449	                    format!("name-status line missing a tab separator: `{line}`"),
 450	                )
 451	            })?;
 452	            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
 453	                return Err(command_malformed_output(
 454	                    "git",
 455	                    args,
 456	                    format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
 457	                ));
 458	            }
 459	            Ok((status.to_string(), path.to_string()))
 460	        })
 461	        .collect()
 462	}
