 474	/// Extracts a manifest's declared version from its already-fetched raw
 475	/// source text. Shared by the batched `git cat-file --batch` path in
 476	/// [`derive_release_commit_decision`] (via [`resolve_batch_versions`]) and
 477	/// this module's own tests (via the single-object `manifest_version_at`
 478	/// helper they define), so both use identical parsing rules.
 479	fn parse_manifest_version(source: &str, path: &str, ecosystem: Ecosystem) -> Result<Version, GraphError> {
 480	    // Every canonical manifest this module ever queries comes from
 481	    // `Package::canonical_manifests()`, which (per `walk.rs`) only ever
 482	    // constructs a `Canonical`-role declaration for Cargo.toml/package.json/
 483	    // pyproject.toml -- the three formats whose ecosystem always has a
 484	    // `canonical_manifest_format`. A miss here means that upstream
 485	    // invariant broke, not that this particular manifest is unsupported.
 486	    let format = ecosystem
 487	        .canonical_manifest_format()
 488	        .ok_or_else(|| GraphError::ReleaseInvariant {
 489	            detail: format!(
 490	                "canonical manifest `{path}` has ecosystem `{}`, which has no canonical manifest format",
 491	                ecosystem.prefix()
 492	            ),
 493	        })?;
 494	    // A malformed blob, a version-less manifest (e.g. a Cargo workspace
 495	    // root with no [package] table, or a `dynamic = ["version"]` PEP 621
 496	    // package), or a Cargo `version.workspace = true` inheritance (which
 497	    // `read_identity` deliberately never resolves, having no workspace
 498	    // context for a historical git blob) all fail closed here rather than
 499	    // panicking or fabricating a version.
 500	    let version = callisto_manifests::read_identity(format, source, std::path::Path::new(path))
 501	        .ok()
 502	        .and_then(|identity| match identity.version {
 503	            Some(callisto_manifests::VersionSource::Literal(v)) => Some(v),
 504	            _ => None,
 505	        })
 506	        .ok_or_else(|| {
 507	            command_malformed_output(
 508	                "git",
 509	                &["cat-file", "--batch"],
 510	                format!("manifest `{path}` has no literal declared version"),
 511	            )
 512	        })?;
 513	    Version::parse(&version, ecosystem.version_grammar()).map_err(GraphError::from)
 514	}
