 724	/// Converts each batched blob-fetch result into the [`Version`] the
 725	/// equivalent single-object `git show` fetch would have produced, using
 726	/// [`parse_manifest_version`]'s parsing rules. A path missing from the
 727	/// queried commit fails closed exactly as a `git show` that couldn't
 728	/// resolve the path would have.
 729	fn resolve_batch_versions(blobs: Vec<BatchBlob>, queries: &[(String, Ecosystem)]) -> Result<Vec<Version>, GraphError> {
 730	    blobs
 731	        .into_iter()
 732	        .zip(queries.iter())
 733	        .map(|(blob, (path, ecosystem))| match blob {
 734	            BatchBlob::Blob(source) => parse_manifest_version(&source, path, *ecosystem),
 735	            BatchBlob::Missing => Err(command_malformed_output(
 736	                "git",
 737	                &["cat-file", "--batch"],
 738	                format!("canonical manifest `{path}` was reported missing at the queried commit"),
 739	            )),
 740	        })
 741	        .collect()
 742	}
