 744	fn reason_from_bump(
 745	    reason: Option<&BumpReason>,
 746	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
 747	) -> Result<ReleaseInclusionReason, GraphError> {
 748	    match reason {
 749	        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
 750	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
 751	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
 752	            group_id: group.to_string(),
 753	        }),
 754	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
 755	            Ok(ReleaseInclusionReason::FixedGroup {
 756	                group_id: group.to_string(),
 757	            })
 758	        }
 759	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
 760	        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
 761	            // `package_ids` is derived from the same workspace graph `via`
 762	            // was resolved against, so a miss (or a non-unique release
 763	            // identity) here means that pairing broke, not that this is a
 764	            // recoverable operator condition.
 765	            let source = package_ids
 766	                .get(via)
 767	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
 768	                .ok_or_else(|| GraphError::ReleaseInvariant {
 769	                    detail: format!(
 770	                        "cascade source package `{}` has no unique release package id",
 771	                        via.display_name()
 772	                    ),
 773	                })?;
 774	            Ok(ReleaseInclusionReason::Cascade {
 775	                from: source,
 776	                edge_kind: format!("{dep_kind:?}"),
 777	            })
 778	        }
 779	        Some(BumpReason::PeerEscalation { via, .. }) => {
 780	            let source = package_ids
 781	                .get(via)
 782	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
 783	                .ok_or_else(|| GraphError::ReleaseInvariant {
 784	                    detail: format!(
 785	                        "peer-escalation source package `{}` has no unique release package id",
 786	                        via.display_name()
 787	                    ),
 788	                })?;
 789	            Ok(ReleaseInclusionReason::Cascade {
 790	                from: source,
 791	                edge_kind: "peer".to_string(),
 792	            })
 793	        }
 794	        Some(_) => Err(GraphError::UnsupportedRelease {
 795	            feature: UnsupportedReleaseFeature::BumpReason,
 796	        }),
 797	    }
 798	}
