 991	    /// Records every `run`/`run_with_stdin` invocation and answers each the
 992	    /// way a real `git` would for this test's fixed fixture, so
 993	    /// `derive_release_commit_decision` can be driven entirely in-memory.
 994	    /// `batch_calls` is the assertion this test cares about: it must land
 995	    /// on exactly 2 (one `cat-file --batch` per commit) no matter how many
 996	    /// canonical manifests `FixedManifestGraph` declares, proving the fix
 997	    /// replaced 2*N `git show` spawns with 2 total, not N-scaled batches.
 998	    struct CountingBatchRunner {
 999	        release_commit: String,
1000	        parent: String,
1001	        decision_json: String,
1002	        name_status: String,
1003	        /// (commit, path) -> blob content; a path/commit pair with no entry
1004	        /// here is answered as `missing`, matching real `git cat-file
1005	        /// --batch` behavior for a path that doesn't exist at that commit.
1006	        blobs: std::collections::BTreeMap<(String, String), String>,
1007	        run_calls: std::sync::Mutex<Vec<(String, Vec<String>)>>,
1008	        batch_calls: std::sync::Mutex<u32>,
1009	    }
1010	
1011	    impl CommandRunner for CountingBatchRunner {
1012	        fn run(
1013	            &self,
1014	            program: &str,
1015	            args: &[&str],
1016	            _cwd: &std::path::Path,
1017	        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
1018	            self.run_calls
1019	                .lock()
1020	                .unwrap()
1021	                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
1022	
1023	            let ok = |stdout: String| {
1024	                Ok(callisto_model::CommandOutput {
1025	                    exit_code: Some(0),
1026	                    stdout,
1027	                    stderr: String::new(),
1028	                })
1029	            };
1030	            let rev_parse_parent = format!("{}^", self.release_commit);
1031	            let decision_object = format!("{}:.callisto/release-decision.json", self.release_commit);
1032	            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some("HEAD") {
1033	                return ok(self.release_commit.clone());
1034	            }
1035	            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some(rev_parse_parent.as_str()) {
1036	                return ok(self.parent.clone());
1037	            }
1038	            if args.first().copied() == Some("diff-tree") {
1039	                return ok(self.name_status.clone());
1040	            }
1041	            if args.first().copied() == Some("show") && args.get(1).copied() == Some(decision_object.as_str()) {
1042	                return ok(self.decision_json.clone());
1043	            }
1044	            panic!("unexpected `{program} {args:?}` in CountingBatchRunner::run");
1045	        }
1046	
1047	        fn run_with_stdin(
1048	            &self,
1049	            program: &str,
1050	            args: &[&str],
1051	            _cwd: &std::path::Path,
1052	            stdin: &[u8],
1053	        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
1054	            self.run_calls
1055	                .lock()
1056	                .unwrap()
1057	                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
1058	            assert_eq!(program, "git");
1059	            assert_eq!(args, ["cat-file", "--batch"]);
1060	            *self.batch_calls.lock().unwrap() += 1;
1061	
1062	            let requested = std::str::from_utf8(stdin).expect("test stdin is always valid UTF-8");
1063	            let mut stdout = String::new();
1064	            for object in requested.lines() {
1065	                let (commit, path) = object.split_once(':').expect("object identifier must be commit:path");
1066	                match self.blobs.get(&(commit.to_string(), path.to_string())) {
1067	                    Some(content) => {
1068	                        stdout.push_str(&format!("{} blob {}\n{}\n", "0".repeat(40), content.len(), content));
1069	                    }
1070	                    None => {
1071	                        stdout.push_str(&format!("{object} missing\n"));
1072	                    }
1073	                }
1074	            }
1075	            Ok(callisto_model::CommandOutput {
1076	                exit_code: Some(0),
1077	                stdout,
1078	                stderr: String::new(),
1079	            })
1080	        }
1081	    }
