  61	/// Derives the durable roster from a freshly computed version plan.
  62	///
  63	/// The caller supplies the plan from the same workspace observation; this
  64	/// function never inspects `PublishPlan` or a caller-provided release roster.
  65	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
  66	    workspace: &Workspace<'_, R, D>,
  67	    plan: &VersionPlan,
  68	) -> Result<ReleaseDecisionV1, GraphError> {
  69	    let mut package_ids = std::collections::BTreeMap::new();
  70	    for package in workspace.graph.packages() {
  71	        if !crate::config::is_release_unit(&workspace.config, &package.id)? {
  72	            continue;
  73	        }
  74	        let ids = release_package_ids(package)?;
  75	        package_ids.insert(package.id.clone(), ids);
  76	    }
  77	
  78	    let mut entries = Vec::new();
  79	    for bump in &plan.bumps {
  80	        if !crate::config::is_release_unit(&workspace.config, &bump.package)? {
  81	            continue;
  82	        }
  83	        // `plan` is contractually derived from this same workspace
  84	        // observation (see doc comment above), so every bump's package must
  85	        // already be a key here -- a miss means the plan/workspace pairing
  86	        // itself is inconsistent, not a recoverable operator condition.
  87	        let ids = package_ids
  88	            .get(&bump.package)
  89	            .ok_or_else(|| GraphError::ReleaseInvariant {
  90	                detail: format!(
  91	                    "version plan references package `{}`, which is absent from this workspace observation",
  92	                    bump.package.display_name()
  93	                ),
  94	            })?;
  95	        for id in ids {
  96	            // A source-only member can propagate a fixed train bump through
  97	            // an edge; retain the train reason without giving that member
  98	            // a durable release identity.
  99	            let reason =
 100	                match bump.reason.as_ref() {
 101	                    Some(BumpReason::Cascade { via, .. } | BumpReason::PeerEscalation { via, .. })
 102	                        if !crate::config::is_release_unit(&workspace.config, via)? =>
 103	                    {
 104	                        let group = workspace.config.groups.fixed_group_of(via).ok_or_else(|| {
 105	                            GraphError::ReleaseInvariant {
 106	                                detail: format!("dev-only cascade source `{via}` has no coordinated fixed group"),
 107	                            }
 108	                        })?;
 109	                        ReleaseInclusionReason::FixedGroup {
 110	                            group_id: group.name.to_string(),
 111	                        }
 112	                    }
 113	                    reason => reason_from_bump(reason, &package_ids)?,
 114	                };
 115	            entries.push(ReleaseDecisionEntry {
 116	                package: id.clone(),
 117	                target_version: bump.to.clone(),
 118	                reasons: vec![reason],
 119	            });
 120	        }
 121	    }
 122	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
