 125	/// Derives a durable decision for explicit, exact release identities.
 126	///
 127	/// A linked group is one release unit: selecting any member includes every
 128	/// member of that linked group which the version plan selected. All other
 129	/// packages remain outside the authority boundary. The caller must pass
 130	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
 131	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
 132	/// for release authority.
 133	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
 134	    workspace: &Workspace<'_, R, D>,
 135	    plan: &VersionPlan,
 136	    selections: &[ReleasePackageId],
 137	) -> Result<ReleaseDecisionV1, GraphError> {
 138	    let complete = derive_release_decision(workspace, plan)?;
 139	
 140	    let mut seen = std::collections::BTreeSet::new();
 141	    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
 142	        return Err(GraphError::ReleaseSelectionInvalid {
 143	            package: duplicate.clone(),
 144	            reason: ReleaseSelectionInvalidReason::Duplicate,
 145	        });
 146	    }
 147	
 148	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
 149	    for selection in &selected {
 150	        if !complete.entries.iter().any(|entry| &entry.package == *selection) {
 151	            return Err(GraphError::ReleaseSelectionInvalid {
 152	                package: (*selection).clone(),
 153	                reason: ReleaseSelectionInvalidReason::NotInPlan,
 154	            });
 155	        }
 156	    }
 157	
 158	    let linked_groups = complete
 159	        .entries
 160	        .iter()
 161	        .filter(|entry| selected.contains(&entry.package))
 162	        .flat_map(|entry| entry.reasons.iter())
 163	        .filter_map(|reason| match reason {
 164	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
 165	            _ => None,
 166	        })
 167	        .collect::<std::collections::BTreeSet<_>>();
 168	
 169	    let entries = complete
 170	        .entries
 171	        .into_iter()
 172	        .filter(|entry| {
 173	            selected.contains(&entry.package)
 174	                || entry.reasons.iter().any(|reason| {
 175	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
 176	                })
 177	        })
 178	        .collect();
 179	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
 180	}
