 413	    GraphError::ReleaseCommand {
 414	        program: program.to_string(),
 415	        args: args.iter().map(|s| s.to_string()).collect(),
 416	        failure: CommandFailure::NonZeroExit {
 417	            exit_code: output.exit_code,
 418	            stderr: output.stderr.clone(),
 419	        },
 420	    }
