 516	/// One object's content as reported by `git cat-file --batch`, for a single
 517	/// requested `<commit>:<path>`.
 518	enum BatchBlob {
 519	    /// The path resolved to a blob at the queried commit; this is its raw
 520	    /// content.
 521	    Blob(String),
 522	    /// The path did not exist at the queried commit -- e.g. a package's
 523	    /// manifest that was only added later, so it has no blob yet at an
 524	    /// earlier `parent` commit.
 525	    Missing,
 526	}
 527	
 528	/// Issues exactly one `git cat-file --batch` invocation requesting every
 529	/// path in `paths` as `<commit>:<path>`, and returns each result in the
 530	/// same order as `paths`.
 531	///
 532	/// `git cat-file --batch` reads one object identifier per line from stdin
 533	/// and, for each, writes to stdout either:
 534	///
 535	/// ```text
 536	/// <sha> SP <type> SP <size> LF
 537	/// <content: exactly `size` bytes> LF
 538	/// ```
 539	///
 540	/// or, if the object doesn't exist:
 541	///
 542	/// ```text
 543	/// <object> SP missing LF
 544	/// ```
 545	///
 546	/// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
 547	/// more than one object; `<commit>:<path>` syntax should never be
 548	/// ambiguous, but it's checked for explicitly below rather than silently
 549	/// falling through to the blob-header parse.)
 550	///
 551	/// This lets every canonical manifest's content at one commit be fetched in
 552	/// a single subprocess round trip instead of one `git show` per manifest.
 553	///
 554	/// Parsing here is deliberately defensive rather than permissive: this
 555	/// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
 556	/// any framing ambiguity -- an unrecognized header shape, a declared `size`
 557	/// that doesn't fit the remaining output, a missing separator byte right
 558	/// after the declared content length, a non-`blob` object type, or a
 559	/// leftover/truncated tail once every requested path has been accounted
 560	/// for -- fails the whole batch closed rather than guessing. Each expected
 561	/// response is also matched against its exact requested object string
 562	/// (rather than a generic "ends with ` missing`" pattern), so a manifest
 563	/// path that happened to contain a space or colon can't be misread as a
 564	/// different response shape. Silently misattributing one manifest's
 565	/// content to a different path because an undetected desync shifted every
 566	/// later offset would be a far worse failure mode than an outright
 567	/// rejection.
 568	fn batch_manifest_blobs_at<R: CommandRunner>(
 569	    runner: &R,
 570	    root: &std::path::Path,
 571	    commit: &str,
 572	    paths: &[&str],
 573	) -> Result<Vec<BatchBlob>, GraphError> {
 574	    if paths.is_empty() {
 575	        return Ok(Vec::new());
 576	    }
 577	
 578	    const BATCH_ARGS: [&str; 2] = ["cat-file", "--batch"];
 579	
 580	    let mut stdin = String::new();
 581	    let objects: Vec<String> = paths
 582	        .iter()
 583	        .map(|path| {
 584	            let object = format!("{commit}:{path}");
 585	            stdin.push_str(&object);
 586	            stdin.push('\n');
 587	            object
 588	        })
 589	        .collect();
 590	
 591	    let output = runner.run_with_stdin("git", &BATCH_ARGS, root, stdin.as_bytes())?;
 592	    if !output.success() {
 593	        return Err(command_non_zero_exit("git", &BATCH_ARGS, &output));
 594	    }
 595	
 596	    let mut rest = output.stdout.as_str();
 597	    let mut results = Vec::with_capacity(objects.len());
 598	    for object in &objects {
 599	        let (header, after_header) = rest.split_once('\n').ok_or_else(|| {
 600	            command_malformed_output(
 601	                "git",
 602	                &BATCH_ARGS,
 603	                format!("truncated response: missing header line for `{object}`"),
 604	            )
 605	        })?;
 606	
 607	        if header == format!("{object} missing") {
 608	            results.push(BatchBlob::Missing);
 609	            rest = after_header;
 610	            continue;
 611	        }
 612	        if header == format!("{object} ambiguous") {
 613	            return Err(command_malformed_output(
 614	                "git",
 615	                &BATCH_ARGS,
 616	                format!("object `{object}` is ambiguous"),
 617	            ));
 618	        }
 619	
 620	        let mut fields = header.split(' ');
 621	        let sha = fields.next().ok_or_else(|| {
 622	            command_malformed_output(
 623	                "git",
 624	                &BATCH_ARGS,
 625	                format!("header for `{object}` is missing its sha field: `{header}`"),
 626	            )
 627	        })?;
 628	        let object_type = fields.next().ok_or_else(|| {
 629	            command_malformed_output(
 630	                "git",
 631	                &BATCH_ARGS,
 632	                format!("header for `{object}` is missing its type field: `{header}`"),
 633	            )
 634	        })?;
 635	        let size_field = fields.next().ok_or_else(|| {
 636	            command_malformed_output(
 637	                "git",
 638	                &BATCH_ARGS,
 639	                format!("header for `{object}` is missing its size field: `{header}`"),
 640	            )
 641	        })?;
 642	        if fields.next().is_some() {
 643	            // A well-formed header has exactly three space-separated
 644	            // fields; anything else is not a shape this parser understands.
 645	            return Err(command_malformed_output(
 646	                "git",
 647	                &BATCH_ARGS,
 648	                format!("header for `{object}` has more than three fields: `{header}`"),
 649	            ));
 650	        }
 651	        if sha.is_empty() || !sha.chars().all(|c| c.is_ascii_hexdigit()) {
 652	            return Err(command_malformed_output(
 653	                "git",
 654	                &BATCH_ARGS,
 655	                format!("header for `{object}` reports a non-hex sha: `{sha}`"),
 656	            ));
 657	        }
 658	        if object_type != "blob" {
 659	            // Every path requested here is a canonical manifest file, so a
 660	            // resolved object must be a blob; a tree/commit/tag response
 661	            // means the path resolved to something else entirely.
 662	            return Err(command_malformed_output(
 663	                "git",
 664	                &BATCH_ARGS,
 665	                format!("object `{object}` resolved to a `{object_type}`, not a blob"),
 666	            ));
 667	        }
 668	        let size: usize = size_field.parse().map_err(|parse_error| {
 669	            command_malformed_output(
 670	                "git",
 671	                &BATCH_ARGS,
 672	                format!("header for `{object}` has a non-numeric size `{size_field}`: {parse_error}"),
 673	            )
 674	        })?;
 675	
 676	        if size > after_header.len() {
 677	            return Err(command_malformed_output(
 678	                "git",
 679	                &BATCH_ARGS,
 680	                format!("object `{object}` declares size {size}, exceeding the remaining response"),
 681	            ));
 682	        }
 683	        // `.get(..size)` (byte-indexed) rather than raw slicing: if `size`
 684	        // doesn't land on a UTF-8 char boundary this fails closed instead
 685	        // of panicking.
 686	        let content = after_header.get(..size).ok_or_else(|| {
 687	            command_malformed_output(
 688	                "git",
 689	                &BATCH_ARGS,
 690	                format!("object `{object}` declares size {size} that does not land on a UTF-8 boundary"),
 691	            )
 692	        })?;
 693	        let remainder = &after_header[size..];
 694	        // The protocol always emits exactly one LF right after the
 695	        // content, separate from the content itself. Requiring it here
 696	        // catches a desynced `size` (from an earlier, unexpectedly
 697	        // reencoded entry) as an explicit error instead of silently
 698	        // parsing the wrong bytes as this entry's content.
 699	        if remainder.as_bytes().first() != Some(&b'\n') {
 700	            return Err(command_malformed_output(
 701	                "git",
 702	                &BATCH_ARGS,
 703	                format!("object `{object}` content is not followed by the expected newline separator"),
 704	            ));
 705	        }
 706	        results.push(BatchBlob::Blob(content.to_string()));
 707	        rest = &remainder[1..];
 708	    }
 709	
 710	    if !rest.is_empty() {
 711	        // More output than the requested objects account for -- either an
 712	        // extra unexpected reply or a framing desync earlier in the
 713	        // stream. Either way, fail closed rather than ignore it.
 714	        return Err(command_malformed_output(
 715	            "git",
 716	            &BATCH_ARGS,
 717	            "response contained more data than the requested objects account for",
 718	        ));
 719	    }
 720	
 721	    Ok(results)
 722	}
