1399	    /// Architectural sibling-gap guard for workspace-membership authority.
1400	    ///
1401	    /// `Option` is permitted below the reader boundary only for genuinely
1402	    /// absent files or fields. The behavioral table first proves every
1403	    /// format-specific reader stops the immediate locator. The small source
1404	    /// inventory then protects the shared Result boundary and pre-walk
1405	    /// propagation from being bypassed by a future bool, Option, empty-glob,
1406	    /// or best-effort adapter.
1407	    #[test]
1408	    fn membership_authority_readers_and_locator_have_no_fallback_encoding() {
1409	        for (ecosystem, authority_file, malformed, child_file, child_manifest) in [
1410	            (
1411	                "Cargo",
1412	                "Cargo.toml",
1413	                "[workspace]\nmembers = [\"",
1414	                "crates/discoverable/Cargo.toml",
1415	                "[package]\nname = \"discoverable\"\nversion = \"1.0.0\"\n",
1416	            ),
1417	            (
1418	                "uv",
1419	                "pyproject.toml",
1420	                "[tool.uv.workspace",
1421	                "packages/discoverable/pyproject.toml",
1422	                "[project]\nname = \"discoverable\"\nversion = \"1.0.0\"\n",
1423	            ),
1424	            (
1425	                "npm",
1426	                "package.json",
1427	                "{\"workspaces\": [}",
1428	                "packages/discoverable/package.json",
1429	                "{\"name\":\"discoverable\",\"version\":\"1.0.0\"}",
1430	            ),
1431	            (
1432	                "pnpm",
1433	                "pnpm-workspace.yaml",
1434	                "packages: [\"",
1435	                "packages/discoverable/package.json",
1436	                "{\"name\":\"discoverable\",\"version\":\"1.0.0\"}",
1437	            ),
1438	        ] {
1439	            let dir = tempfile::tempdir().unwrap();
1440	            let root = dir.path();
1441	            std::fs::write(root.join(authority_file), malformed).unwrap();
1442	            let child = root.join(child_file);
1443	            std::fs::create_dir_all(child.parent().unwrap()).unwrap();
