+/// Reject source-only identities wherever a durable decision grants authority,
+/// including causal references supplied in a serialized decision.
+pub(crate) fn validate_release_units<R: CommandRunner, D: DependencyResolver>(
+    workspace: &Workspace<'_, R, D>,
+    decision: &ReleaseDecisionV1,
+) -> Result<(), GraphError> {
+    let mut excluded = std::collections::BTreeSet::new();
+    for package in workspace.graph.packages() {
+        if !crate::config::is_release_unit(&workspace.config, &package.id)? {
+            excluded.extend(release_package_ids(package)?);
+        }
+    }
+    for entry in &decision.entries {
+        for id in std::iter::once(&entry.package).chain(entry.reasons.iter().filter_map(|reason| match reason {
+            ReleaseInclusionReason::Cascade { from, .. } => Some(from),
+            _ => None,
+        })) {
+            if excluded.contains(id) {
+                return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
+            }
+        }
+    }
+    Ok(())
+}
