+                "uv",
+                "pyproject.toml",
+                "[tool.uv.workspace",
+                "packages/discoverable/pyproject.toml",
+                "[project]\nname = \"discoverable\"\nversion = \"1.0.0\"\n",
+            ),
+            (
+                "npm",
+                "package.json",
+                "{\"workspaces\": [}",
+                "packages/discoverable/package.json",
+                "{\"name\":\"discoverable\",\"version\":\"1.0.0\"}",
+            ),
+            (
+                "pnpm",
+                "pnpm-workspace.yaml",
+                "packages: [\"",
+                "packages/discoverable/package.json",
+                "{\"name\":\"discoverable\",\"version\":\"1.0.0\"}",
+            ),
+        ] {
+            let dir = tempfile::tempdir().unwrap();
+            let root = dir.path();
+            std::fs::write(root.join(authority_file), malformed).unwrap();
+            let child = root.join(child_file);
+            std::fs::create_dir_all(child.parent().unwrap()).unwrap();
+            std::fs::write(child, child_manifest).unwrap();
+
+            match crate::ProjectLocator::projects(&crate::IgnoreWalkLocator::new(root)) {
+                Err(crate::LocateError::MembershipParse {
+                    ecosystem: reported, ..
+                }) => assert_eq!(reported, ecosystem, "{ecosystem} must fail before admitting its child"),
+                other => panic!("{ecosystem} malformed authority must fail closed before walking, got {other:?}"),
+            }
+        }
+
+        let membership = include_str!("../locate/membership.rs");
+        let locator = include_str!("../locate/ignore_walk.rs");
+        let root = include_str!("../locate/root.rs");
+        let cli_workspace = include_str!("../../../callisto-cli/src/workspace.rs");
+        let cli_release = include_str!("../../../callisto-cli/src/commands/release.rs");
+
+        for reader in [
+            "read_membership(",
+            "read_cargo_membership(",
+            "read_python_membership(",
+            "read_package_json_membership(",
+            "read_pnpm_membership(",
+            "read_npm_membership(",
+        ] {
+            let signature = membership
+                .find(&format!("fn {reader}"))
+                .unwrap_or_else(|| panic!("membership reader `{reader}` must remain inventoried"));
+            let source_after_signature = &membership[signature..];
+            let signature_end = source_after_signature
+                .find('{')
+                .unwrap_or_else(|| panic!("membership reader `{reader}` must have a body"));
+            assert!(
