    #[test]
    fn dev_only_dependency_consumers_do_not_relay_release_bumps() {
        for dependency_table in ["dependencies", "build-dependencies"] {
            for group_kind in [None, Some("fixed-group"), Some("linked-group")] {
                for gamma_also_depends_on_alpha in [false, true] {
                    let dir = tempfile::tempdir().unwrap();
                    let root = dir.path();
                    fs::write(
                        root.join("Cargo.toml"),
                        "[workspace]\nmembers = ['alpha', 'beta', 'gamma']\n",
                    )
                    .unwrap();
                    let mut config = "[[package]]\nmatch = 'cargo/beta'\nrelease-unit = 'dev-only'\n".to_string();
                    if let Some(kind) = group_kind {
                        config.push_str(&format!(
                            "[[{kind}]]\nname = 'source-train'\nmembers = ['alpha', 'beta']\n"
                        ));
                    }
                    fs::write(root.join("callisto.toml"), config).unwrap();
                    for name in ["alpha", "beta", "gamma"] {
                        let path = root.join(name);
                        fs::create_dir_all(&path).unwrap();
                        let mut source = format!("[package]\nname = '{name}'\nversion = '1.0.0'\n");
                        if name == "beta" {
                            source.push_str(&format!(
                                "[{dependency_table}]\nalpha = {{ path = '../alpha', version = '=1.0.0' }}\n"
                            ));
                        } else if name == "gamma" {
                            source.push_str("[dependencies]\nbeta = { path = '../beta', version = '=1.0.0' }\n");
                            if gamma_also_depends_on_alpha {
                                source.push_str("alpha = { path = '../alpha', version = '=1.0.0' }\n");
                            }
                        }
                        fs::write(path.join("Cargo.toml"), source).unwrap();
                    }
                    fs::create_dir_all(root.join(".changeset")).unwrap();
                    fs::write(
                        root.join(".changeset/alpha.md"),
                        "---\nalpha: major\n---\n\nAlpha breaking change.\n",
                    )
                    .unwrap();
                    git(root, &["init", "-q"]);
                    git(root, &["config", "user.name", "Release test"]);
                    git(root, &["config", "user.email", "release-test@example.invalid"]);
                    git(root, &["add", "."]);
                    git(root, &["commit", "-qm", "base"]);
                    for name in ["alpha", "gamma"] {
                        git(root, &["tag", &format!("{name}@1.0.0")]);
                    }

                    let locator = IgnoreWalkLocator::new(root);
                    let ws = Workspace::load(root.to_path_buf(), &locator, &GitRunner).unwrap();
                    let plan = plan_version(&ws, &NoInference, &VersionOptions::default()).unwrap();
                    assert_eq!(
                        plan.bumps.iter().any(|bump| bump.package.name() == "beta"),
                        group_kind.is_some()
                    );
                    assert_eq!(
                        plan.bumps.iter().any(|bump| bump.package.name() == "gamma"),
                        gamma_also_depends_on_alpha
                    );
                    assert!(plan.rewrites.iter().any(|rewrite| rewrite.dependency.name() == "alpha" && matches!(&rewrite.key.target, callisto_graph::cascade::DepWriteTarget::Manifest(path) if path == Path::new("beta/Cargo.toml"))));
                    let decision = derive_release_decision(&ws, &plan).unwrap();
                    assert_eq!(decision.entries.len(), if gamma_also_depends_on_alpha { 2 } else { 1 });
                    assert!(decision.entries.iter().all(|entry| entry.package.name() != "beta" && entry.reasons.iter().all(|reason| !matches!(reason, ReleaseInclusionReason::Cascade { from, .. } if from.name() == "beta"))));
                    apply_version_plan(
                        root,
                        &plan,
                        &GitRunner,
                        &ApplyOptions::default(),
                        &ApplyPermit::force_for_tests(),
                    )
                    .unwrap();
                    drop(ws);
                    fs::create_dir_all(root.join(".callisto")).unwrap();
                    let decision_path = Path::new(".callisto/release-decision.json");
                    fs::write(root.join(decision_path), serde_json::to_vec(&decision).unwrap()).unwrap();
                    git(root, &["add", "."]);
                    git(root, &["commit", "-qm", "version"]);
                    let commit = CommitSha::parse(&git(root, &["rev-parse", "HEAD"])).unwrap();
                    let ws = Workspace::load(root.to_path_buf(), &locator, &GitRunner).unwrap();
                    assert_eq!(
                        derive_release_commit_decision(&ws, &commit, decision_path).unwrap(),
                        decision
                    );
                }
            }
        }
    }
}

/// Verifies that the custom branch name passed via `--branch` appears in the
/// rendered PR body, not the default branch inferred from config.
#[test]
fn test_compose_pr_body_custom_branch_flag() {
    use callisto_graph::commands::{compose_pr_body, PrBodyOptions};
    use callisto_graph::infer::NoInference;

    struct DummyRunner;
    impl callisto_model::CommandRunner for DummyRunner {
        fn run(
            &self,
            _program: &str,
            _args: &[&str],
            _cwd: &std::path::Path,
        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
            Ok(callisto_model::CommandOutput {
                exit_code: Some(0),
                stdout: "".to_string(),
                stderr: "".to_string(),
            })
        }
    }

    let runner = DummyRunner;
    let ws_dir = tempfile::tempdir().unwrap();
    let cfg = callisto_graph::config::load(&ws_dir.path().join("callisto.toml")).unwrap();
    let graph = GraphBuilder::new().build().unwrap();
    let git = callisto_vcs::GitAccess::discover(ws_dir.path(), &runner);
    let tags = callisto_graph::tags::TagIndex::build(&git, &graph, &cfg).unwrap();
    let ws = callisto_graph::Workspace {
        root: ws_dir.path().to_path_buf(),
        config: cfg,
        graph,
        tags: OnceCell::from(tags),
        git: OnceCell::from(git),
        runner: &runner,
        manifest_cache: Default::default(),
        identity: callisto_graph::IdentityIndex::default(),
    };

    let inference = NoInference;
    let opts = PrBodyOptions {
        existing_body: None,
        branch: Some("release/v1.0".to_string()),
    };

    let report = compose_pr_body(&ws, &inference, &opts).unwrap();
    assert!(report.body.contains("release/v1.0"));
}

/// Verifies that `apply_version_plan` surfaces a `git add` failure instead
/// of silently reporting the path as staged. This covers the error path where
/// the manifest write succeeds but the subsequent `git add` exits non-zero.
#[test]
fn test_apply_version_plan_reports_git_add_failure() {
    use callisto_graph::apply::{apply_version_plan, ApplyOptions};
    use callisto_graph::plan::VersionPlan;
    use callisto_model::{CommandOutput, CommandRunner};

    struct FailingGitAddRunner;
    impl CommandRunner for FailingGitAddRunner {
        fn run(
            &self,
            program: &str,
            args: &[&str],
            _cwd: &std::path::Path,
        ) -> Result<CommandOutput, callisto_model::CommandError> {
            if program == "git" && args.first() == Some(&"add") {
                return Ok(CommandOutput {
                    exit_code: Some(1),
                    stdout: String::new(),
                    stderr: "fatal: pathspec rejected by hook".to_string(),
                });
            }
            Ok(CommandOutput {
                exit_code: Some(0),
                stdout: String::new(),
                stderr: String::new(),
            })
        }
    }

    let runner = FailingGitAddRunner;
    let ws_dir = tempfile::tempdir().unwrap();
    std::process::Command::new("git")
        .arg("init")
        .current_dir(ws_dir.path())
        .output()
        .unwrap();

    let pre_state = callisto_format::PreState::entering("canary", Vec::new());
    let plan = VersionPlan {
        pre_state_update: Some(pre_state),
        ..Default::default()
    };

    let opts = ApplyOptions {
        refresh_lockfiles: false,
        transient: false,
    };

    let result = apply_version_plan(ws_dir.path(), &plan, &runner, &opts, &ApplyPermit::force_for_tests());

    assert!(
        result.is_err(),
        "expected apply_version_plan to return an error when `git add` fails, got: {result:?}"
    );
}

